from lib import *
S = SS('x72')
steps = [
    step("激活 profile 的方式与优先级。什么都不设:active=[],default=[default],app.v 来自 application.properties 的 base,@Profile(\"default\") 的 Bean 是生效的。application.properties 里写 spring.profiles.active=dev:active=[dev],app.v=dev。-Dspring.profiles.active=dev,prod:active=[dev, prod],两个文件都写了 app.v,后面的 prod 赢。环境变量 SPRING_PROFILES_ACTIVE=qa:active=[qa]。命令行 --spring.profiles.active=prod 压过文件里的 dev;系统属性 prod 压过环境变量 qa(和第 69 篇的来源优先级一致)。代码里 setAdditionalProfiles(\"qa\") 再配命令行 dev:active=[qa, dev];spring.profiles.include=qa 再配命令行 dev,结果也是 [qa, dev],追加的排在前面,所以 app.v 仍然来自 dev。spring.profiles.default=fallback:没有激活任何 profile 时 default=[fallback],app.v=fallback,@Profile(\"default\") 的 Bean 不再生效;只要激活了 dev,default 就被忽略,app.v 是 dev。", t=tl(S(1)), mark=lidx(S(1), '-Dspring.profiles.active=dev,prod', 'setAdditionalProfiles', 'spring.profiles.include=qa', 'spring.profiles.default=fallback(没有'), done=lidx(S(1), '什么都不设', 'application.properties 里写 spring.profiles.active=dev', '环境变量 SPRING_PROFILES_ACTIVE=qa', '命令行 --spring.profiles.active=prod', '系统属性 -Dspring.profiles.active=prod,环境变量'), b=bars([['什么都不设:激活的 profile 个数', 0, '0'], ['-D dev,prod', 2, '2'], ['setAdditionalProfiles(qa) + 命令行 dev', 2, '2'], ['include=qa + 命令行 dev', 2, '2'], ['命令行 prod 压过文件里的 dev', 1, '1']], 2, done=[0, 4], mark=[1, 2, 3]), kv=KV([['来源', '命令行 > 系统属性 > 环境变量 > 配置文件'], ['多个 profile', '后面的文件赢'], ['include / additionalProfiles', '追加的排在前面'], ['default', '只在没有激活任何 profile 时才用']], ['多个 profile'])),
    step("@Profile 表达式。9 个 Bean,标签就是各自的 @Profile:dev、!prod、\"dev & cloud\"、\"dev | test\"、\"(dev | test) & !cloud\"、数组 {x, y}、default、数组 {dev, !cloud}、\"dev,test\"(带逗号)。逐个激活不同的 profile 看哪些 Bean 生效:不激活任何 profile:!prod、default、{dev, !cloud} 共 3 个;激活 dev:dev、!prod、dev | test、(dev | test) & !cloud、{dev, !cloud} 共 5 个;激活 prod:只剩 {dev, !cloud} 1 个;激活 dev 和 cloud:dev、!prod、dev & cloud、dev | test、{dev, !cloud} 共 5 个;激活 test:4 个;激活 x:!prod、{x, y}、{dev, !cloud} 共 3 个;激活 cloud:只有 !prod 1 个。三个容易误会的地方:数组写法 {dev, !cloud} 是「或」,所以没有任何 profile、只激活 prod、只激活 x 的时候它都生效;带逗号的 \"dev,test\" 不是「dev 或 test」,激活 dev 或 test 它都没有生效;profile 名称区分大小写,激活 Dev 时 @Profile(\"dev\") 的 Bean 不生效。写错表达式:\"dev & cloud | test\"(混用 & 和 | 又不加括号)启动抛 IllegalArgumentException「Malformed profile expression」,激活 dev 和不激活任何 profile 都一样;@Profile(\"\") 抛「Invalid profile expression []: must contain text」;而括号不闭合的 \"(dev | test\" 和缺右侧的 \"dev &\" 反而能正常启动,激活 dev 时 Bean 存在,不激活 profile 时不存在。", t=tl(S(2)), mark=lidx(S(2), '激活 [prod]', '激活 [cloud]', '激活 [Dev]', 'dev & cloud | test', '(dev | test', 'dev &"'), done=lidx(S(2), '激活 [无]', '激活 [dev]:', '激活 [dev,cloud]', '激活 [test]', '激活 [x]'), b=bars([['不激活任何 profile:生效的 Bean 个数(数出来的)', 3, '3'], ['激活 dev', 5, '5'], ['激活 prod', 1, '1'], ['激活 dev 和 cloud', 5, '5'], ['激活 test', 4, '4'], ['激活 x', 3, '3'], ['激活 cloud', 1, '1'], ['激活 Dev(大写)', 2, '2']], 5, done=[0, 1, 3, 4, 5], mark=[2, 6, 7]), kv=KV([['数组 {a, b}', '是「或」'], ['\"a,b\"', '不是「或」,是一个叫 a,b 的名字'], ['混用 & 和 |', '要加括号,否则启动抛 Malformed'], ['名称', '区分大小写']], ['数组 {a, b}'])),
    step("profile 组与 include。application.properties 里写 spring.profiles.group.prod=proddb,prodmq,激活 prod 得到 active=[prod, proddb, prodmq];application-prod / proddb / prodmq 三个文件里 proddb 写 app.v=db、db.url,prodmq 写 app.v=mq、mq.host,最终 app.v=mq(列表里靠后的 prodmq 赢),db.url 和 mq.host 都读得到。组里顺序反过来写成 prodmq,proddb,active=[prod, prodmq, proddb],app.v 变成 db。没有激活 prod 时组不生效,active=[],app.v 是 null。组可以套:group.a=b、group.b=c,激活 a 得到 [a, b, c]。两种写错:spring.profiles.include 写在 application-prod.properties 里,启动抛 InvalidConfigDataPropertyException,说它在 profile 专属文件里无效;spring.profiles.group.prod 写在 application-prod.properties 里,不报错,但也没有生效,active 仍然只有 [prod]。", t=tl(S(3)), mark=lidx(S(3), '写在 application-prod.properties 里(profile 专属文件)', 'spring.profiles.include=proddb 写在', '不激活 prod'), done=lidx(S(3), 'group.prod=proddb,prodmq,激活 prod', '顺序反过来', '组里套组'), b=bars([['group.prod=proddb,prodmq 激活 prod:active 个数', 3, '3'], ['套组 a→b→c 激活 a:active 个数', 3, '3'], ['不激活 prod:active 个数', 0, '0'], ['group 写在 application-prod.properties 里:active 个数', 1, '1']], 3, done=[0, 1], mark=[2, 3]), kv=KV([['group', '激活 prod 时一并激活 proddb、prodmq,按写的顺序,靠后的赢'], ['组套组', '可以,会展开'], ['include', '写在 profile 专属文件里启动失败'], ['group 写在 profile 专属文件里', '不报错,也不生效']], ['group'])),
    step("多个 profile 的文件顺序与名称。application-a.properties 和 application-b.properties 都写 app.v:--spring.profiles.active=a,b 得到 b(only.a、only.b 都读得到);b,a 得到 a——谁写在后面谁赢,不看字母顺序。profile 名称:dev_1、dev-1、dev.1、dev+x、dev@x 5 种都被接受(没有对应文件,所以 app.v 是 null);dev$x 启动失败,报「Profile 'dev$x' must contain a letter, digit or allowed char ('-', '_', '.', '+', '@')」;带空格的 \"dev x\" 绑定 spring.profiles.active 时失败,同样是这个错;空字符串得到 active=[],不报错。", t=tl(S(4)), mark=lidx(S(4), 'dev$x', '"dev x"', '--spring.profiles.active="":'), done=lidx(S(4), 'active=a,b', 'active=b,a', 'dev_1', 'dev-1', 'dev.1', 'dev+x', 'dev@x'), b=bars([['被接受的名字个数(dev_1、dev-1、dev.1、dev+x、dev@x)', 5, '5'], ['启动失败的名字个数(dev$x、\"dev x\")', 2, '2'], ['空字符串得到的 active 个数', 0, '0']], 5, done=[0], mark=[1, 2]), kv=KV([['a,b vs b,a', '写在后面的赢,不看字母'], ['允许的字符', '字母数字和 - _ . + @'], ['非法名字', '启动失败'], ['空字符串', 'active=[]']], ['a,b vs b,a'])),
    step("spring.profiles.active 写在不该写的地方。extra72.properties 由 @PropertySource 加载,里面写了 spring.profiles.active=dev:Environment.getProperty(\"spring.profiles.active\") 读到 dev(来源就是这个文件),但 active=[]——application-dev.properties 没有加载,app.v 是 null,@Profile 的结果和没有任何 profile 时一样(!prod、default、{dev, !cloud})。同样的内容写在 application.properties 里:active=[dev],app.v=dev,@Profile(\"dev\") 的 Bean 生效。也就是说「能读到这个属性」和「profile 被激活了」是两回事:激活 profile 要靠 Boot 在加载配置文件时读取的来源(命令行、系统属性、环境变量、application 配置文件),@PropertySource 太晚了。", t=tl(S(5)), mark=lidx(S(5), 'spring.profiles.active = dev ←| classpath', 'active=[] default=[default]'), done=lidx(S(5), 'active=[dev]', 'app.v = dev'), b=bars([['@PropertySource 里写 active=dev:激活的 profile 个数', 0, '0'], ['application.properties 里写 active=dev:激活的 profile 个数', 1, '1']], 1, done=[1], mark=[0]), kv=KV([['@PropertySource', '属性读得到,profile 没激活'], ['application.properties', '激活'], ['原因', '配置文件阶段只看 Boot 约定的来源'], ['对照', 'getProperty 能读到 ≠ profile 已激活']], ['@PropertySource'])),
]
A = mkartx('x72', 72, 'Spring,Boot,Profile,profile组,配置,真实验证,动画演示',
    '实测 Spring Boot 4 的 profile:激活方式(命令行 > 系统属性 > 环境变量 > 配置文件)与 include、additionalProfiles、default 的行为;9 种 @Profile 写法的逐个对照(数组是「或」,带逗号的不是,名称区分大小写,混用 & 和 | 要加括号);profile 组的展开顺序;多个 profile 里后写的赢;写在 @PropertySource 里的 spring.profiles.active 读得到却不激活。',
    'spring.profiles.active 写在命令行、环境变量、配置文件里谁说了算?@Profile({"dev","!cloud"}) 是「或」还是「且」?profile 组的顺序影响谁覆盖谁?为什么把 spring.profiles.active 写进 @PropertySource 没有用?这篇在 Spring Boot 4.0.8 上逐个场景实测。',
    [('9 个 Bean', '逐个激活 profile 对照 @Profile 的 9 种写法;激活 dev 时 5 个生效,激活 prod 时只剩 1 个'), ('prod → proddb, prodmq', 'group.prod=proddb,prodmq 激活 prod 得到 [prod, proddb, prodmq],app.v 来自靠后的 prodmq;顺序反过来就是 proddb'), ('0 个', '写在 @PropertySource 文件里的 spring.profiles.active=dev:getProperty 读得到 dev,激活的 profile 是 0 个')],
    [('激活方式与优先级', '<p>命令行 > 系统属性 > 环境变量 > 配置文件;include 和 additionalProfiles 追加在前面;default 只在没激活任何 profile 时才用。</p>'),
     ('@Profile 表达式', '<p>数组是「或」,带逗号的字符串不是;混用 & 和 | 要加括号;名称区分大小写。</p>'),
     ('profile 组', '<p>激活组名时按写的顺序一并激活成员,靠后的覆盖靠前的;组可以套;include 和 group 不能写在 profile 专属文件里。</p>'),
     ('名称与文件顺序', '<p>多个 profile 写在后面的赢;名称只允许字母、数字和 - _ . + @。</p>'),
     ('写错位置', '<p>@PropertySource 里的 spring.profiles.active 读得到但不激活 profile。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8(spring-boot-starter,非 Web 模式)的单个程序,每个场景一个独立 JVM;配置文件放在临时工作目录;@Profile 的 9 个 Bean 都是普通 @Bean 方法,用返回的标签判断是否生效;写错表达式的场景是单独再编译了一个只含一个 @Profile 的程序',
     '没有验证:测试里的 @ActiveProfiles;Environment.acceptsProfiles 的各种用法;Kubernetes 或 Docker 里用环境变量传 profile 的细节;Spring Cloud Config 按 profile 取配置;profile 名称与配置文件名大小写的关系(本机文件系统不区分大小写,这类结果不可靠,所以只测了 @Profile 的大小写比较);为什么括号不闭合的表达式能通过(我只观察到结果,没有读 Profiles 解析器的源码)'],
    'profile')
